/* ============================================================
   QUEUE ORACLE - Hospital Queue & Resource Prediction System
   Primary Styling: Professional Medical Tech Dashboard
   Palette: Clean white & light blue background, dark navy sidebar
   ============================================================ */

:root {
    --bg-main: #f4f8fb;
    --bg-card: #ffffff;
    --navy-dark: #0b1a30;
    --navy-sidebar: #10243e;
    --navy-sidebar-hover: #1b3558;
    --navy-active: #1976d2;
    --text-primary: #1e293b;
    --text-secondary: #64748b;
    --text-muted: #94a3b8;
    --primary-blue: #0284c7;
    --primary-light: #e0f2fe;
    --accent-cyan: #06b6d4;

    /* Medical Status Colors */
    --status-normal: #10b981;
    --status-normal-bg: #ecfdf5;
    --status-warning: #f59e0b;
    --status-warning-bg: #fffbeb;
    --status-critical: #ef4444;
    --status-critical-bg: #fef2f2;

    --border-color: #e2e8f0;
    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 12px rgba(15, 23, 42, 0.07);
    --radius-md: 10px;
    --radius-lg: 14px;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    background-color: var(--bg-main);
    color: var(--text-primary);
    margin: 0;
    padding: 0;
    overflow-x: hidden;
}

/* ---------------- Layout & Sidebar ---------------- */
#app-container {
    display: flex;
    min-height: 100vh;
}

#sidebar {
    width: 270px;
    background: linear-gradient(180deg, var(--navy-dark) 0%, var(--navy-sidebar) 100%);
    color: #ffffff;
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    position: fixed;
    top: 0;
    bottom: 0;
    left: 0;
    z-index: 1000;
    overflow-y: auto;
    border-right: 1px solid rgba(255, 255, 255, 0.08);
}

#sidebar::-webkit-scrollbar {
    width: 5px;
}
#sidebar::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 4px;
}

.brand-section {
    padding: 1.25rem 1.25rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.brand-title {
    font-size: 1.15rem;
    font-weight: 800;
    letter-spacing: 0.5px;
    color: #38bdf8;
    margin: 0;
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

.brand-subtitle {
    font-size: 0.72rem;
    color: var(--text-muted);
    margin-top: 0.2rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
}

.sidebar-nav {
    list-style: none;
    padding: 0.75rem 0.6rem;
    margin: 0;
    flex-grow: 1;
}

.sidebar-nav .nav-header {
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #64748b;
    padding: 0.6rem 0.8rem 0.3rem;
    letter-spacing: 0.6px;
}

.sidebar-nav .nav-link {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.55rem 0.85rem;
    color: #cbd5e1;
    font-size: 0.86rem;
    font-weight: 500;
    border-radius: 8px;
    text-decoration: none;
    transition: all 0.2s ease;
    margin-bottom: 0.2rem;
    cursor: pointer;
}

.sidebar-nav .nav-link:hover {
    background-color: var(--navy-sidebar-hover);
    color: #ffffff;
    transform: translateX(3px);
}

.sidebar-nav .nav-link.active {
    background-color: var(--navy-active);
    color: #ffffff;
    font-weight: 600;
    box-shadow: 0 2px 8px rgba(2, 132, 199, 0.35);
}

.sidebar-nav .nav-link i {
    width: 18px;
    text-align: center;
    font-size: 0.95rem;
}

.sidebar-nav .nav-badge {
    margin-left: auto;
    font-size: 0.7rem;
    padding: 0.15rem 0.45rem;
    border-radius: 12px;
}

.sidebar-footer {
    padding: 1rem;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 0.75rem;
    color: var(--text-muted);
    background-color: rgba(0, 0, 0, 0.15);
}

/* ---------------- Main Content Area ---------------- */
#main-content {
    margin-left: 270px;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.top-navbar {
    background-color: #ffffff;
    border-bottom: 1px solid var(--border-color);
    padding: 0.75rem 1.75rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    position: sticky;
    top: 0;
    z-index: 900;
}

.page-container {
    padding: 1.5rem 1.75rem;
    flex-grow: 1;
}

/* ---------------- Section Toggle ---------------- */
.dashboard-section {
    display: none;
    animation: fadeIn 0.25s ease-in-out;
}

.dashboard-section.active {
    display: block;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
}

/* ---------------- Cards & Widgets ---------------- */
.card-widget {
    background-color: var(--bg-card);
    border-radius: var(--radius-lg);
    border: 1px solid var(--border-color);
    box-shadow: var(--shadow-sm);
    padding: 1.25rem;
    margin-bottom: 1.25rem;
    transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.card-widget:hover {
    box-shadow: var(--shadow-md);
}

.widget-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 1rem;
    padding-bottom: 0.6rem;
    border-bottom: 1px solid #f1f5f9;
}

.widget-title {
    font-size: 1rem;
    font-weight: 700;
    color: var(--navy-dark);
    margin: 0;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.widget-title i {
    color: var(--primary-blue);
}

/* ---------------- Stat Cards ---------------- */
.stat-card {
    background-color: #ffffff;
    border: 1px solid var(--border-color);
    border-radius: var(--radius-lg);
    padding: 1.15rem 1.25rem;
    box-shadow: var(--shadow-sm);
    display: flex;
    align-items: center;
    justify-content: space-between;
    position: relative;
    overflow: hidden;
    margin-bottom: 1rem;
}

.stat-card::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
}

.stat-card.blue::before { background-color: var(--primary-blue); }
.stat-card.green::before { background-color: var(--status-normal); }
.stat-card.yellow::before { background-color: var(--status-warning); }
.stat-card.red::before { background-color: var(--status-critical); }
.stat-card.cyan::before { background-color: var(--accent-cyan); }

.stat-info .stat-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 0.25rem;
}

.stat-info .stat-value {
    font-size: 1.65rem;
    font-weight: 800;
    color: var(--navy-dark);
    line-height: 1.1;
}

.stat-info .stat-sub {
    font-size: 0.72rem;
    color: var(--text-muted);
    margin-top: 0.3rem;
}

.stat-icon {
    width: 46px;
    height: 46px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.3rem;
}

.stat-icon.blue { background-color: var(--primary-light); color: var(--primary-blue); }
.stat-icon.green { background-color: var(--status-normal-bg); color: var(--status-normal); }
.stat-icon.yellow { background-color: var(--status-warning-bg); color: var(--status-warning); }
.stat-icon.red { background-color: var(--status-critical-bg); color: var(--status-critical); }
.stat-icon.cyan { background-color: #cffafe; color: #0891b2; }

/* ---------------- Status Badges ---------------- */
.badge-status {
    padding: 0.3rem 0.65rem;
    font-size: 0.72rem;
    font-weight: 700;
    border-radius: 6px;
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    letter-spacing: 0.3px;
}

.badge-normal, .badge-NORMAL, .badge-success {
    background-color: var(--status-normal-bg);
    color: #065f46;
    border: 1px solid #a7f3d0;
}

.badge-warning, .badge-WARNING, .badge-MODERATE {
    background-color: var(--status-warning-bg);
    color: #92400e;
    border: 1px solid #fde68a;
}

.badge-critical, .badge-CRITICAL, .badge-OVERLOADED, .badge-danger {
    background-color: var(--status-critical-bg);
    color: #991b1b;
    border: 1px solid #fecaca;
}

.badge-info {
    background-color: #f0f9ff;
    color: #0369a1;
    border: 1px solid #bae6fd;
}

/* ---------------- Professional Tables ---------------- */
.table-custom {
    width: 100%;
    margin-bottom: 0;
    border-collapse: separate;
    border-spacing: 0;
}

.table-custom th {
    background-color: #f8fafc;
    color: var(--text-secondary);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 0.75rem 1rem;
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
    vertical-align: middle;
}

.table-custom td {
    padding: 0.75rem 1rem;
    font-size: 0.85rem;
    color: var(--text-primary);
    border-bottom: 1px solid #f1f5f9;
    vertical-align: middle;
}

.table-custom tbody tr:hover {
    background-color: #f8fafc;
}

/* ---------------- Priority Indicators ---------------- */
.priority-pill {
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-size: 0.72rem;
    font-weight: 700;
}
.priority-emergency { background-color: #fee2e2; color: #b91c1c; border-left: 3px solid #dc2626; }
.priority-medium { background-color: #fef3c7; color: #b45309; border-left: 3px solid #f59e0b; }
.priority-normal { background-color: #f1f5f9; color: #475569; border-left: 3px solid #94a3b8; }

/* ---------------- Buttons & Controls ---------------- */
.btn-oracle {
    font-size: 0.82rem;
    font-weight: 600;
    padding: 0.45rem 0.85rem;
    border-radius: 8px;
    transition: all 0.2s ease;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
}

.btn-oracle-primary {
    background-color: var(--primary-blue);
    color: #ffffff;
    border: none;
}
.btn-oracle-primary:hover {
    background-color: #0369a1;
    color: #ffffff;
}

.btn-oracle-success {
    background-color: #10b981;
    color: #ffffff;
    border: none;
}
.btn-oracle-success:hover {
    background-color: #059669;
    color: #ffffff;
}

.btn-oracle-danger {
    background-color: #ef4444;
    color: #ffffff;
    border: none;
}
.btn-oracle-danger:hover {
    background-color: #dc2626;
    color: #ffffff;
}

.btn-oracle-warning {
    background-color: #f59e0b;
    color: #ffffff;
    border: none;
}
.btn-oracle-warning:hover {
    background-color: #d97706;
    color: #ffffff;
}

/* ---------------- Token Pill ---------------- */
.token-badge {
    background: #0f172a;
    color: #38bdf8;
    padding: 0.25rem 0.55rem;
    border-radius: 6px;
    font-family: monospace;
    font-size: 0.9rem;
    font-weight: 700;
    display: inline-block;
}

/* ---------------- Simulation Floating / Banner ---------------- */
.sim-indicator {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.75rem;
    border-radius: 20px;
    background-color: #fef3c7;
    border: 1px solid #fde68a;
    color: #92400e;
    font-size: 0.75rem;
    font-weight: 600;
}

.sim-indicator .dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: #f59e0b;
    animation: pulse 1.5s infinite;
}

@keyframes pulse {
    0% { transform: scale(0.95); opacity: 0.8; }
    50% { transform: scale(1.2); opacity: 1; }
    100% { transform: scale(0.95); opacity: 0.8; }
}

/* ---------------- Toast Notification ---------------- */
#toast-container {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 9999;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.oracle-toast {
    background: #ffffff;
    border-left: 4px solid var(--primary-blue);
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.15);
    border-radius: 8px;
    padding: 0.85rem 1.15rem;
    min-width: 280px;
    max-width: 400px;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    animation: slideInRight 0.3s ease;
}

.oracle-toast.success { border-left-color: var(--status-normal); }
.oracle-toast.danger { border-left-color: var(--status-critical); }
.oracle-toast.warning { border-left-color: var(--status-warning); }

@keyframes slideInRight {
    from { transform: translateX(100%); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
}

/* ---------------- Responsive ---------------- */
@media (max-width: 992px) {
    #sidebar {
        width: 70px;
    }
    #sidebar .brand-title span,
    #sidebar .brand-subtitle,
    #sidebar .nav-header,
    #sidebar .nav-link span,
    #sidebar .nav-badge,
    #sidebar .sidebar-footer {
        display: none;
    }
    #sidebar .nav-link {
        justify-content: center;
        padding: 0.75rem 0;
    }
    #main-content {
        margin-left: 70px;
    }
}

/**
 * QUEUE ORACLE - Data Visualization Module (Chart.js)
 * Implements all 9 charts dynamically connected to real backend endpoints.
 */

const OracleCharts = {
    instances: {},

    // Helper to safely re-create or update a chart
    createOrUpdate(canvasId, config) {
        if (this.instances[canvasId]) {
            this.instances[canvasId].destroy();
        }
        const ctx = document.getElementById(canvasId);
        if (!ctx) return null;
        this.instances[canvasId] = new Chart(ctx, config);
        return this.instances[canvasId];
    },

    // 1. Overview: Patients Waiting by Department
    renderDeptWaitingChart(departments) {
        const labels = departments.map(d => d.name);
        const data = departments.map(d => d.waiting_patients);
        const bgColors = departments.map(d => {
            if (d.status === "CRITICAL") return "#ef4444";
            if (d.status === "WARNING") return "#f59e0b";
            return "#0284c7";
        });

        this.createOrUpdate("chartDeptWaiting", {
            type: "bar",
            data: {
                labels: labels,
                datasets: [{
                    label: "Waiting Patients",
                    data: data,
                    backgroundColor: bgColors,
                    borderRadius: 6
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: false },
                    tooltip: {
                        callbacks: {
                            label: (ctx) => `Waiting Patients: ${ctx.raw}`
                        }
                    }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        ticks: { stepSize: 2 }
                    }
                }
            }
        });
    },

    // 2. Overview / Forecast: Hourly Predicted Patient Arrivals
    renderArrivalsChart(forecastData) {
        this.createOrUpdate("chartArrivalsForecast", {
            type: "line",
            data: {
                labels: forecastData.hours,
                datasets: [
                    {
                        label: "Actual Arrivals",
                        data: forecastData.actual_arrivals,
                        borderColor: "#0284c7",
                        backgroundColor: "rgba(2, 132, 199, 0.15)",
                        fill: true,
                        tension: 0.35,
                        pointRadius: 4,
                        pointBackgroundColor: "#0284c7"
                    },
                    {
                        label: "Predicted Arrivals (Oracle AI)",
                        data: forecastData.predicted_arrivals,
                        borderColor: "#8b5cf6",
                        borderDash: [5, 5],
                        backgroundColor: "transparent",
                        tension: 0.35,
                        pointRadius: 3,
                        pointBackgroundColor: "#8b5cf6"
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { position: "top" }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: "Patients / Hour" }
                    }
                }
            }
        });
    },

    // 3. Bed Occupancy: Occupied vs Available
    renderBedDonutChart(overall) {
        this.createOrUpdate("chartBedDonut", {
            type: "doughnut",
            data: {
                labels: ["Occupied Beds", "Available Beds"],
                datasets: [{
                    data: [overall.occupied_beds, overall.available_beds],
                    backgroundColor: ["#ef4444", "#10b981"],
                    hoverOffset: 4,
                    borderWidth: 2
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                cutout: "70%",
                plugins: {
                    legend: { position: "bottom" }
                }
            }
        });
    },

    // 4. Doctor Workload: Active Patient Load
    renderDoctorWorkloadChart(doctors) {
        const labels = doctors.map(d => d.name.replace("Dr. ", ""));
        const waiting = doctors.map(d => d.waiting_count);
        const inConsult = doctors.map(d => d.active_consults);

        this.createOrUpdate("chartDoctorWorkload", {
            type: "bar",
            data: {
                labels: labels,
                datasets: [
                    {
                        label: "In Consultation",
                        data: inConsult,
                        backgroundColor: "#10b981",
                        borderRadius: 4
                    },
                    {
                        label: "Waiting in Queue",
                        data: waiting,
                        backgroundColor: "#0284c7",
                        borderRadius: 4
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: { stacked: true },
                    y: { stacked: true, beginAtZero: true }
                },
                plugins: {
                    legend: { position: "top" }
                }
            }
        });
    },

    // 5. Waiting Time Trends by Hour
    renderWaitTimeTrendsChart(hours, waitData) {
        this.createOrUpdate("chartWaitTimeTrends", {
            type: "line",
            data: {
                labels: hours,
                datasets: [{
                    label: "Avg Waiting Time (Minutes)",
                    data: waitData,
                    borderColor: "#f59e0b",
                    backgroundColor: "rgba(245, 158, 11, 0.12)",
                    fill: true,
                    tension: 0.35,
                    pointRadius: 4,
                    pointBackgroundColor: "#f59e0b"
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: "Minutes" }
                    }
                }
            }
        });
    },

    // 6. Disease Trends (14-day history)
    renderDiseaseTrendsChart(diseaseList) {
        if (!diseaseList || diseaseList.length === 0) return;
        const dates = diseaseList[0].history_dates || [];
        const colors = ["#ef4444", "#3b82f6", "#10b981", "#f59e0b", "#8b5cf6"];

        const datasets = diseaseList.map((d, idx) => ({
            label: `${d.disease_name} (Verified)`,
            data: d.history_cases,
            borderColor: colors[idx % colors.length],
            backgroundColor: "transparent",
            tension: 0.3,
            borderWidth: 2,
            pointRadius: 3
        }));

        this.createOrUpdate("chartDiseaseTrends", {
            type: "line",
            data: {
                labels: dates,
                datasets: datasets
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { position: "top" },
                    title: { display: true, text: "Epidemiological Surveillance (Last 14 Days)" }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: "Daily Cases Count" }
                    }
                }
            }
        });
    },

    // 7. Bed Forecast (1h to 4h by department)
    renderBedForecastChart(departments) {
        const labels = ["Current", "+1 Hour", "+2 Hours", "+3 Hours", "+4 Hours"];
        const colors = ["#0284c7", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6", "#ec4899"];

        const datasets = departments.map((dept, idx) => {
            const dataPoints = [
                dept.occupancy_rate,
                ...dept.hourly_forecasts.map(h => h.projected_percentage)
            ];
            return {
                label: dept.department,
                data: dataPoints,
                borderColor: colors[idx % colors.length],
                tension: 0.25,
                borderWidth: 2,
                pointRadius: 4
            };
        });

        this.createOrUpdate("chartBedForecast", {
            type: "line",
            data: {
                labels: labels,
                datasets: datasets
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { position: "top" }
                },
                scales: {
                    y: {
                        min: 30,
                        max: 105,
                        title: { display: true, text: "Occupancy Rate (%)" }
                    }
                }
            }
        });
    },

    // 8. Inventory Availability vs Min Stock
    renderInventoryChart(inventoryItems) {
        const topItems = inventoryItems.slice(0, 7);
        const labels = topItems.map(i => i.item_name.length > 18 ? i.item_name.substring(0, 18) + "..." : i.item_name);
        const available = topItems.map(i => i.available_qty);
        const minStock = topItems.map(i => i.min_stock);

        this.createOrUpdate("chartInventory", {
            type: "bar",
            data: {
                labels: labels,
                datasets: [
                    {
                        label: "Available Stock",
                        data: available,
                        backgroundColor: topItems.map(i => i.shortage_risk === "CRITICAL" ? "#ef4444" : (i.shortage_risk === "WARNING" ? "#f59e0b" : "#10b981")),
                        borderRadius: 4
                    },
                    {
                        label: "Minimum Safety Stock",
                        data: minStock,
                        backgroundColor: "#cbd5e1",
                        borderRadius: 4
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { position: "top" }
                },
                scales: {
                    y: { beginAtZero: true }
                }
            }
        });
    },

    // 9. Machine Learning Feature Importance
    renderFeatureImportanceChart(features) {
        if (!features) return;
        const labels = features.map(f => f.feature);
        const data = features.map(f => f.importance);

        this.createOrUpdate("chartFeatureImportance", {
            type: "bar",
            data: {
                labels: labels,
                datasets: [{
                    label: "Importance Weight (%)",
                    data: data,
                    backgroundColor: "#0284c7",
                    borderRadius: 4
                }]
            },
            options: {
                indexAxis: "y",
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: false }
                },
                scales: {
                    x: {
                        beginAtZero: true,
                        title: { display: true, text: "Percentage (%)" }
                    }
                }
            }
        });
    }
};

