// UI Notification Toast
function showToast(message, type = "info") {
    const container = document.getElementById("toast-container");
    if (!container) return;

    const toast = document.createElement("div");
    toast.className = `oracle-toast ${type}`;
    let icon = "fa-info-circle text-primary";
    if (type === "success") icon = "fa-check-circle text-success";
    if (type === "danger") icon = "fa-exclamation-triangle text-danger";
    if (type === "warning") icon = "fa-exclamation-circle text-warning";

    toast.innerHTML = `
        <i class="fas ${icon} fa-lg"></i>
        <div class="flex-grow-1">${message}</div>
    `;
    container.appendChild(toast);

    setTimeout(() => {
        toast.style.opacity = "0";
        toast.style.transform = "translateX(100%)";
        setTimeout(() => toast.remove(), 300);
    }, 4000);
}

// Navigation Handler
function navigateTo(sectionId) {
    OracleState.currentSection = sectionId;

    // Update sidebar active class
    document.querySelectorAll(".sidebar-nav .nav-link").forEach(link => {
        if (link.dataset.section === sectionId) {
            link.classList.add("active");
        } else {
            link.classList.remove("active");
        }
    });

    // Update visible section
    document.querySelectorAll(".dashboard-section").forEach(sec => {
        if (sec.id === `section-${sectionId}`) {
            sec.classList.add("active");
        } else {
            sec.classList.remove("active");
        }
    });

    // Load data specific to this section
    switch (sectionId) {
        case "overview":
            loadOverview();
            break;
        case "patients":
            loadPatients();
            break;
        case "queue":
            loadQueue();
            break;
        case "prediction":
            // Ready for lookup
            break;
        case "doctors":
            loadDoctors();
            break;
        case "forecast":
            loadResourceForecast();
            break;
        case "beds":
            loadBeds();
            break;
        case "disease":
            loadDiseaseTrends();
            break;
        case "inventory":
            loadInventory();
            break;
        case "recommendations":
            loadRecommendations();
            break;
        case "insights":
            loadInsights();
            break;
        case "simulation":
            loadSimulationControls();
            break;
        case "ml-performance":
            loadMLPerformance();
            break;
        case "about":
            // Static guide
            break;
    }
}

// Clock updates
function updateClock() {
    const el = document.getElementById("live-clock");
    if (el) {
        const now = new Date();
        el.textContent = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    }
}

